/*
// Definition for a Node.
class Node {
public:
    int val;
    vector<Node*> children;

    Node() {}

    Node(int _val) {
        val = _val;
    }

    Node(int _val, vector<Node*> _children) {
        val = _val;
        children = _children;
    }
};
*/

class Solution {
public:
    vector<int> preorder(Node* root)
    {
        vector<int> pre_vec ;
        stack<Node *> stk ;
        stk.push(root);
        while(!stk.empty())
        {
            Node *curr = stk.top() ;
            stk.pop() ;       
            if(curr)
            {
                pre_vec.push_back(curr->val) ;
                vector<Node *>::iterator i1 = (curr->children).end();
                while(i1!=(curr->children).begin())
                {
                    i1-- ;
                    stk.push(*i1);
                }
            }
        }
        return pre_vec ;
    }
};
